using UnityEngine;
namespace CafeLife {
 public sealed class CafeTableBlackjack:MonoBehaviour {
  public bool Opened {get;private set;} public Vector3 Center {get;private set;} GameObject layout;CafeGame game;CafeCasino casino;Vector3 returnPosition;Quaternion returnRotation;float returnPitch,returnFov;
  public void Enter(CafeGame owner){game=owner;casino=owner.GetComponent<CafeCasino>();if(!casino)casino=owner.gameObject.AddComponent<CafeCasino>();if(!Opened)Center=new Vector3(Mathf.Abs(owner.player.transform.position.x-8)<Mathf.Abs(owner.player.transform.position.x-15)?8:15,5.23f,-33);if(!Opened){returnPosition=owner.player.transform.position;returnRotation=owner.player.transform.rotation;returnPitch=owner.player.pitch;returnFov=owner.player.view.fieldOfView;}Opened=true;owner.Continue();owner.player.body.enabled=false;owner.player.transform.position=new Vector3(Center.x,4.65f,Center.z+2.15f);owner.player.transform.rotation=Quaternion.Euler(0,180,0);owner.player.body.enabled=true;owner.player.pitch=32;owner.player.view.transform.localRotation=Quaternion.Euler(32,0,0);owner.player.view.fieldOfView=52;Refresh();owner.Tell("Masadaki fiş veya karta bak · E / ETKİLEŞ");}
  public bool CanUse=>Opened&&game&&!game.player.WorldInputBlocked&&Mathf.Abs(game.player.transform.position.y-4.2f)<1.2f&&Vector3.Distance(game.player.transform.position,Center)<5;
  public void Action(string action){if(!CanUse)return;if(action=="hit")casino.Hit();else if(action=="stand")casino.Stand();else if(action=="leave"){if(casino.Active)casino.Stand();Opened=false;game.player.body.enabled=false;game.player.transform.position=returnPosition;game.player.transform.rotation=returnRotation;game.player.body.enabled=true;game.player.pitch=returnPitch;game.player.view.transform.localRotation=Quaternion.Euler(returnPitch,0,0);game.player.view.fieldOfView=returnFov;if(layout)Destroy(layout);game.Tell("Masadan ayrıldın.");}else if(int.TryParse(action,out int bet))casino.StartHand(bet);}
  public void Refresh(){if(!Opened||!game)return;if(layout){layout.SetActive(false);Destroy(layout);}layout=new GameObject("Masada blackjack canlı kartlar");layout.transform.SetParent(game.world.transform,false);layout.transform.position=Center;
   foreach(var item in game.world.GetComponentsInChildren<Transform>(true))if((item.name=="Casino kapalı iskambil"||item.name=="Casino ince fiş")&&Mathf.Abs(item.position.x-Center.x)<2.2f&&Mathf.Abs(item.position.z-Center.z)<2)item.gameObject.SetActive(false);
   Print("Krupiye · "+(casino.Active?"?":CafeCasino.Score(casino.dealer).ToString()),new Vector3(0,.014f,-.85f),new Vector2(1.5f,.14f),new Color(.86f,.76f,.5f));
   Cards(casino.dealer,-.42f,true);Cards(casino.player,.20f,false);
   Print(casino.Active?"Sen: "+CafeCasino.Score(casino.player):casino.Result,new Vector3(0,.014f,.53f),new Vector2(2.6f,.14f),Color.white);
   if(casino.Active){Button("Kart çek","hit",-.65f);Button("Dur","stand",0);}else{Button("10 coin","10",-.95f);Button("50 coin","50",-.35f);Button("200 coin","200",.25f);}Button("Ayrıl","leave",.95f);
  }
  void Cards(System.Collections.Generic.List<int> cards,float z,bool dealer){for(int i=0;i<cards.Count;i++){bool hidden=dealer&&casino.Active&&i>0;float x=(i-(cards.Count-1)*.5f)*Mathf.Min(.38f,2.4f/Mathf.Max(1,cards.Count));var card=GameObject.CreatePrimitive(PrimitiveType.Cube);card.name=hidden?"Kapalı krupiye kartı":"Açık blackjack kartı";card.transform.SetParent(layout.transform,false);card.transform.localPosition=new Vector3(x,.009f,z);card.transform.localScale=new Vector3(.32f,.012f,.44f);card.GetComponent<Renderer>().sharedMaterial=game.world.ColorMaterial(hidden?new Color(.12f,.16f,.3f):new Color(.94f,.92f,.84f));Destroy(card.GetComponent<Collider>());if(!hidden){int id=cards[i],rank=id%13+1;string face=rank==1?"A":rank==11?"J":rank==12?"Q":rank==13?"K":rank.ToString();Print(face+"\n"+new[]{"Maça","Kupa","Karo","Sinek"}[id/13],new Vector3(x,.018f,z),new Vector2(.27f,.35f),id/13==1||id/13==2?new Color(.55f,.06f,.05f):new Color(.06f,.08f,.1f));}}}
  void Button(string label,string action,float x){var chip=GameObject.CreatePrimitive(PrimitiveType.Cube);chip.name="Masa eylemi · "+label;chip.transform.SetParent(layout.transform,false);chip.transform.localPosition=new Vector3(x,.025f,.88f);chip.transform.localScale=new Vector3(.52f,.045f,.28f);chip.GetComponent<Renderer>().sharedMaterial=game.world.ColorMaterial(new Color(.14f,.22f,.19f));Destroy(chip.GetComponent<Collider>());var hit=new GameObject("Masa dokunma alanı");hit.transform.SetParent(layout.transform,false);hit.transform.localPosition=new Vector3(x,.08f,.88f);hit.layer=8;var box=hit.AddComponent<BoxCollider>();box.isTrigger=true;box.size=new Vector3(.54f,.18f,.3f);hit.AddComponent<CafeTarget>().kind="blackjack_"+action;Print(label,new Vector3(x,.052f,.88f),new Vector2(.46f,.2f),new Color(.98f,.85f,.55f));}
  void Print(string value,Vector3 at,Vector2 area,Color color){var text=new GameObject("Masaya basılı yazı").AddComponent<TextMesh>();text.transform.SetParent(layout.transform,false);text.transform.localPosition=at;text.transform.localRotation=Quaternion.Euler(90,180,0);text.text=value;text.fontSize=48;text.characterSize=.025f;text.anchor=TextAnchor.MiddleCenter;text.alignment=TextAlignment.Center;text.color=color;text.gameObject.AddComponent<CafeDepthLabel>().Setup(text,CafeTypography.Strong);text.gameObject.AddComponent<CafePrintedLabel>().area=area;}
 }
}
